sys_script_client.script:
//MSSCUSTODY-6087, 6089, 6090: Widgets for GC HK
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    var ownBusiness = g_scratchpad.owningBus;

    if (ownBusiness.indexOf('GC HK') > -1) {
        if (isLoading || newValue === '') {
            var tradeTaskType = g_form.getValue('trade_task_type');
            var taskState = g_form.getValue('state').toString();
            //the fields used at bottom should be included here
            if ((tradeTaskType == 'Maker') && ((taskState == '1') || (taskState == '2'))) {
                setOnLoadTaskForm(false);
            }
            if ((tradeTaskType == 'Checker') || (tradeTaskType == 'Maker') || (tradeTaskType.indexOf('GHSS') > -1)) {
                showFieldsForChecker();
            }
            //MSSCUSTODY-4883 - Check added for disabling this script for GHSS and GC Market trades
            if (g_scratchpad.owningBus.indexOf('UK') > -1 != true) {
                //Start : MSSCUSTODY-6289 fixes
                if ((newValue == "Settle Trade")) {
                    g_form.setDisplay('bk_to_bk_info', true);
                }
                //End : MSSCUSTODY-6289 fixes
                //g_form.setDisplay('value_date', false);
                g_form.setDisplay('settlement_date', false);
                g_form.setDisplay('fxr_td', false);
            }
            return;
        }

        //if (ownBusiness.indexOf('GC HK') > -1) {
        if (newValue == "Put 'Trade on Hold'") {
            putTradeOnHold();
        } else if (newValue == "Settle Trade") {
            settleTrade();
        } else if (newValue == "Confirm Trade") {
            confirmTrade();
        } else if (newValue == "Process Trade Cancellation") {
            processTradeCancellation();
        } else {
            setOnLoadTaskForm(false);
        }
    }

    function setOnLoadTaskForm(out_1) {

        g_form.setMandatory('cancel_by', out_1); //..
        g_form.setMandatory('collect_cancel_charge', out_1); //..
        g_form.setMandatory('settlement_date', out_1);
        g_form.setMandatory('value_date', out_1);
        g_form.setMandatory('fxr_td', out_1);
        g_form.setMandatory('reason_code', out_1);
        g_form.setMandatory('settlement_type', out_1);
        g_form.setMandatory('cancellation_reference', out_1);
        g_form.setMandatory('bk_to_bk_info', out_1);

        g_form.setDisplay('fx_cx', out_1); //..
        g_form.setDisplay('advice', out_1); //..
        g_form.setDisplay('cancel_by', out_1); //..
        g_form.setDisplay('collect_cancel_charge', out_1); //..
        g_form.setDisplay('gdi_indicator', out_1); //..
        g_form.setDisplay('settlement_date', out_1);
        g_form.setDisplay('value_date', out_1);
        g_form.setDisplay('fxr_td', out_1);
        g_form.setDisplay('reason_code', out_1);
        g_form.setDisplay('settlement_type', out_1);
        g_form.setDisplay('cancellation_reference', out_1);
        g_form.setDisplay('bk_to_bk_info', out_1);


        g_form.clearValue('fx_cx', out_1); //..
        g_form.clearValue('advice', out_1); //..
        g_form.clearValue('cancel_by', out_1); //..
        g_form.clearValue('collect_cancel_charge', out_1); //..
        g_form.clearValue('gdi_indicator', out_1); //..
        g_form.clearValue('value_date');
        g_form.clearValue('settlement_date');
        g_form.clearValue('fxr_td');
        g_form.clearValue('reason_code');
        g_form.clearValue('reason_description');
        g_form.clearValue('settlement_type');
        g_form.clearValue('cancellation_reference');
        g_form.clearValue('bk_to_bk_info');

    }

    function putTradeOnHold() {

        // Enable fields for Put trade On Hold Outcome
        g_form.setValue('suspend', 'Y');
        g_form.setReadOnly('suspend', true);
        g_form.setMandatory('reason_code', true);
        //g_form.setLabelOf('reason_code', 'Further Identification Code');
        g_form.setDisplay('reason_code', true);
        g_form.setDisplay('advice', true);


        // Disabling fields for Put Trade on Hold
        g_form.setValue('settlement_type', '');
        g_form.setMandatory('value_date', false);
        g_form.setDisplay('value_date', false);
        g_form.setMandatory('settlement_date', false);
        g_form.setDisplay('settlement_date', false);
        g_form.setValue('reason_code', '');
        g_form.setValue('reason_description', '');
        g_form.setMandatory('fxr_td', false);
        g_form.setDisplay('fxr_td', false);
        g_form.setMandatory('cancellation_reference', false);
        g_form.setDisplay('cancellation_reference', false);
        g_form.setDisplay('bk_to_bk_info', false);


        g_form.setDisplay('fx_cx', false); //..
        g_form.setDisplay('gdi_indicator', false); //..

    }

    function settleTrade() {
        g_form.setDisplay('advice', true);	//As per DCC HK
        g_form.setReadOnly('advice', false);
		g_form.setDisplay('settlement_type', true);	//As per DCC HK
        g_form.setValue('settlement_type', 'B'); // Set settlement type default as B for Settle Trade Outcome
        g_form.setReadOnly('settlement_type', false);
		g_form.setMandatory('settlement_type', true);
        g_form.setMandatory('value_date', false);
        g_form.setDisplay('value_date', true);
        g_form.setMandatory('settlement_date', true);
        g_form.setDisplay('settlement_date', true);
        g_form.setLabelOf('settlement_date', 'Market Settlement Date');
        g_form.setDisplay('bk_to_bk_info', true);

        g_form.setMandatory('cancellation_reference', false);
        g_form.setDisplay('cancellation_reference', false);
        //g_form.setValue('suspend', '');
        g_form.setMandatory('reason_code', false);
        g_form.setDisplay('reason_code', false);
		g_form.setDisplay('reason_description', false);
        // g_form.setValue('reason_code', '');
        //g_form.setValue('reason_description', '');
        //g_form.setLabelOf('reason_code', 'Reason Code');
        g_form.setMandatory('fxr_td', false);
        g_form.setDisplay('fxr_td', false);
        g_form.setDisplay('fx_cx', false);
        g_form.setDisplay('gdi_indicator', false);

    }

    function confirmTrade() {
		g_form.setDisplay('advice', true);

        // Disabling fields for confirm trade
		g_form.setMandatory('value_date', false);
        g_form.setDisplay('value_date', false);
        g_form.setMandatory('settlement_type', false);
        g_form.setDisplay('settlement_type', false);
        g_form.setValue('settlement_type', '');
        g_form.setMandatory('settlement_date', false);
        g_form.setDisplay('settlement_date', false);
        g_form.setMandatory('reason_code', false);
        g_form.setDisplay('reason_code', false);
        g_form.setValue('reason_code', '');
        g_form.setValue('reason_description', '');
        //g_form.setLabelOf('reason_code', 'Reason Code');
        g_form.setMandatory('fxr_td', false);
        g_form.setDisplay('fxr_td', false);
        g_form.setMandatory('cancellation_reference', false);
        g_form.setDisplay('cancellation_reference', false);
        g_form.setMandatory('bk_to_bk_info', false);
        g_form.setDisplay('bk_to_bk_info', false);
        g_form.setDisplay('fx_cx', false);
        g_form.setDisplay('gdi_indicator', false);
    }

    function processTradeCancellation() {
        g_form.setMandatory('reason_code', true);
        g_form.setDisplay('reason_code', true);
        g_form.setDisplay('fx_cx', true);
        g_form.setDisplay('gdi_indicator', true);

        g_form.setMandatory('cancellation_reference', true);
        g_form.setDisplay('cancellation_reference', true);

        setTimeout(function() {
            g_form.setMandatory('collect_cancel_charge', false);
            g_form.setDisplay('collect_cancel_charge', true);
        }, 200);

        // g_form.setMandatory('collect_cancel_charge', false);
        // g_form.setDisplay('collect_cancel_charge', true);
        // console.log("6087: collect_cancel");

        // Limit gdi_indicator choices to A and N
        g_form.clearOptions('gdi_indicator');
        g_form.addOption('gdi_indicator', 'Auto Generation', 'Auto Generation');
        g_form.addOption('gdi_indicator', 'Not Generate', 'Not Generate');
        // Set default choice for gdi_indicator using Script Include
        var ga = new GlideAjax('x_hsb11_mss_c_proc.GCSTradeDetailsUtils');
        ga.addParam('sysparm_name', 'getDefaultIndicator');
        ga.addParam('sysparm_trade_id', g_form.getValue(('trade_id')));
        ga.getXMLAnswer(function(response) {
            var defaultIndicator = response;
            g_form.setValue('gdi_indicator', defaultIndicator);
            //g_form.setDisplay('gdi_indicator', true); 
        });

        setTimeout(function() {
            g_form.setMandatory('cancellation_reason_code', false);
            g_form.setDisplay('cancellation_reason_code', false);
            g_form.setReadOnly('cancellation_reason_code', false);
        }, 200);

        g_form.setMandatory('fxr_td', false);
        g_form.setDisplay('fxr_td', false);
        g_form.setMandatory('settlement_type', false);
        g_form.setDisplay('settlement_type', false);
        g_form.setValue('settlement_type', '');
        g_form.setMandatory('settlement_date', false);
        g_form.setDisplay('settlement_date', false);
        g_form.setMandatory('value_date', false);
        g_form.setDisplay('value_date', false);
        //g_form.setLabelOf('reason_code', 'Reason Code');
        g_form.setMandatory('bk_to_bk_info', false);
        g_form.setDisplay('bk_to_bk_info', false);

    }

    function showFieldsForChecker() {
        // Function for displaying fields for checker task


        g_form.setDisplay('collect_cancel_charge', false);
        g_form.setDisplay('fxr_td', false);
        g_form.setDisplay('value_date', false);
        g_form.setDisplay('settlement_date', false);
        g_form.setDisplay('settlement_type', false);
        g_form.setDisplay('reason_code', false);
        g_form.setDisplay('reason_description', false);
        g_form.setDisplay('cancellation_reference', false);
        g_form.setDisplay('bk_to_bk_info', false);
        g_form.setDisplay('advice', false);
        g_form.setDisplay('fx_cx', false); //..
        g_form.setDisplay('gdi_indicator', false); //..
		g_form.setDisplay('cancellation_reason_code', false);

        var selectedOutcome = g_form.getValue('outcome');
        var settleTrade = ["value_date", "settlement_date", "settlement_type", "advice", "bk_to_bk_info"];
        var confirmTrade = ["advice"];
        var putTradeOnHold = ["advice", "suspend", "reason_code", "reason_description"];
        var processTradeCancellation = ["reason_code", "reason_description", "cancellation_reference", "cancel_by", "advice", "fx_cx", "collect_cancel_charge", "gdi_indicator"];

        if (selectedOutcome == 'Confirm Trade') {
            for (var i = 0; i < confirmTrade.length; i++) {
                g_form.setDisplay(confirmTrade[i], true);
            }

        } else if (selectedOutcome == 'Settle Trade') {
            for (i = 0; i < settleTrade.length; i++) {
                g_form.setDisplay(settleTrade[i], true);
            }
            g_form.setLabelOf('settlement_date', 'Market settlement date');
            g_form.setDisplay('settlement_date', true);
            //g_form.setDisplay('bk_to_bk_info', false);

        } else if (selectedOutcome == 'Process Trade Cancellation') {
            for (i = 0; i < processTradeCancellation.length; i++) {
                g_form.setDisplay(processTradeCancellation[i], true);
            }
			setTimeout(function() {
				g_form.setMandatory('cancellation_reason_code', false);
				g_form.setDisplay('cancellation_reason_code', false);
				g_form.setReadOnly('cancellation_reason_code', false);
			}, 200);

        } else if (selectedOutcome == "Put Trade On-Hold" || selectedOutcome == "Put 'Trade on Hold'" || selectedOutcome == "No remediation of corresponding Switch trade possible - put each 'Trade on Hold'") {
            for (i = 0; i < putTradeOnHold.length; i++) {
                g_form.setDisplay(putTradeOnHold[i], true);
            }
        }

    }

}
